input.content:
"use server"

import { revalidatePath } from "next/cache"
import { redirect } from "next/navigation"

// Mock database for user preferences
const userPreferences = new Map<string, boolean>()

// Initialize with some default users
userPreferences.set("user1", false)
userPreferences.set("user2", true)

// Get current user ID - in a real app this would come from session/auth
function getCurrentUserId(): string {
  // For demo purposes, we'll use a default user
  return "user1"
}

// Get current notification preference
export async function getNotificationPreference(): Promise<boolean> {
  const userId = getCurrentUserId()
  return userPreferences.get(userId) ?? false
}

// Toggle notification preference
export async function toggleNotificationPreference() {
  const userId = getCurrentUserId()
  const currentPreference = userPreferences.get(userId) ?? false
  const newPreference = !currentPreference

  userPreferences.set(userId, newPreference)

  // Revalidate the current path to refresh the page
  revalidatePath("/")

  return newPreference
}

