input.newString:
import { toggleNotificationPreference, getNotificationPreference } from "./actions/notification"

export default async function Home() {
  const notificationPreference = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotificationPreference}>
        <div>
          <label htmlFor="notifications">Enable Notifications</label>
          <input
            type="checkbox"
            id="notifications"
            name="notifications"
            checked={notificationPreference}
            onChange={async () => {
              await toggleNotificationPreference()
            }}
          />
          <span>{notificationPreference ? "On" : "Off"}</span>
        </div>
        <button type="submit">Toggle Notifications</button>
      </form>
    </main>
  );
}

